using UnityEngine;
namespace Alterverse.UI
{
public sealed class MainMenuController:MonoBehaviour
{
private enum Page{Home,Heroes,Settings}private static MainMenuController instance;private Page page;private bool visible=true;private GUIStyle title,subtitle,button,small,panel,heroName;private Texture2D dimTexture,zeroTexture,lumenTexture;private int selectedHero;private readonly string[] heroes={"VEYR","KAELON","NYRA","ELYRA","MIRA","ROOK"};private readonly string[] roles={"ASSASSINE","TANK","MARKSMAN","MAGIER","SUPPORT","BRUISER"};
[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]private static void AutoCreate(){if(FindAnyObjectByType<MainMenuController>()==null)new GameObject("DF_MainMenu").AddComponent<MainMenuController>();}
private void Awake(){if(instance!=null&&instance!=this){Destroy(gameObject);return;}instance=this;Time.timeScale=0f;dimTexture=MakeTexture(new Color(.012f,.008f,.028f,.96f));zeroTexture=MakeTexture(new Color(.18f,.035f,.28f,.32f));lumenTexture=MakeTexture(new Color(.025f,.36f,.42f,.25f));}
private Texture2D MakeTexture(Color c){Texture2D t=new(1,1);t.SetPixel(0,0,c);t.Apply();return t;}private void OnDestroy(){if(instance==this)instance=null;if(dimTexture!=null)Destroy(dimTexture);if(zeroTexture!=null)Destroy(zeroTexture);if(lumenTexture!=null)Destroy(lumenTexture);}
private void OnGUI(){if(!visible)return;EnsureStyles();DrawBackground();switch(page){case Page.Heroes:DrawHeroes();break;case Page.Settings:DrawSettings();break;default:DrawHome();break;}}
private void DrawBackground(){GUI.DrawTexture(new Rect(0,0,Screen.width,Screen.height),dimTexture);GUI.DrawTexture(new Rect(0,0,Screen.width*.48f,Screen.height),zeroTexture);GUI.DrawTexture(new Rect(Screen.width*.52f,0,Screen.width*.48f,Screen.height),lumenTexture);float seam=Mathf.Max(3,Screen.width*.004f);GUI.Box(new Rect(Screen.width*.5f-seam*.5f,0,seam,Screen.height),GUIContent.none);}
private void DrawHome(){float w=Mathf.Min(660f,Screen.width*.88f),x=(Screen.width-w)*.5f,top=Screen.height*.17f;GUI.Label(new Rect(x,top,w,86),"DIMENSIONS FRONT",title);GUI.Label(new Rect(x,top+76,w,34),"FIGHT FOR YOUR REALITY",subtitle);float bw=Mathf.Min(380f,w*.76f),bx=(Screen.width-bw)*.5f,by=Mathf.Max(top+180,Screen.height*.48f);if(GUI.Button(new Rect(bx,by,bw,62),"SPIELEN",button))Play();if(GUI.Button(new Rect(bx,by+76,bw,52),"HELDEN",button))page=Page.Heroes;GUI.enabled=false;GUI.Button(new Rect(bx,by+140,bw,52),"RANGLISTE  •  BALD",button);GUI.enabled=true;if(GUI.Button(new Rect(bx,by+204,bw,48),"EINSTELLUNGEN",button))page=Page.Settings;GUI.Label(new Rect(x,Screen.height-50,w,24),"EARLY PROTOTYPE",small);}
private void DrawHeroes(){float w=Mathf.Min(760f,Screen.width*.9f),x=(Screen.width-w)*.5f;GUI.Label(new Rect(x,Screen.height*.12f,w,58),"HELDEN",title);GUI.Box(new Rect(x,Screen.height*.27f,w,190),GUIContent.none,panel);if(GUI.Button(new Rect(x+18,Screen.height*.27f+65,55,55),"‹",button))selectedHero=(selectedHero+heroes.Length-1)%heroes.Length;if(GUI.Button(new Rect(x+w-73,Screen.height*.27f+65,55,55),"›",button))selectedHero=(selectedHero+1)%heroes.Length;GUI.Label(new Rect(x+80,Screen.height*.27f+38,w-160,62),heroes[selectedHero],heroName);GUI.Label(new Rect(x+80,Screen.height*.27f+100,w-160,36),roles[selectedHero],subtitle);GUI.Label(new Rect(x+80,Screen.height*.27f+137,w-160,28),$"{selectedHero+1} / {heroes.Length}",small);if(GUI.Button(new Rect(x,Screen.height*.27f+215,180,48),"ZURÜCK",button))page=Page.Home;}
private void DrawSettings(){float w=Mathf.Min(620f,Screen.width*.86f),x=(Screen.width-w)*.5f;GUI.Label(new Rect(x,Screen.height*.14f,w,62),"EINSTELLUNGEN",title);GUI.Box(new Rect(x,Screen.height*.30f,w,150),GUIContent.none,panel);GUI.Label(new Rect(x+25,Screen.height*.30f+30,w-50,34),"AUDIO, GRAFIK UND STEUERUNG",subtitle);GUI.Label(new Rect(x+25,Screen.height*.30f+78,w-50,28),"Wird nach dem Gameplay-Test aktiviert.",small);if(GUI.Button(new Rect(x,Screen.height*.30f+180,180,48),"ZURÜCK",button))page=Page.Home;}
private void Play(){visible=false;Time.timeScale=1f;gameObject.SetActive(false);}
private void EnsureStyles(){if(title!=null)return;title=new GUIStyle(GUI.skin.label){fontSize=Mathf.Clamp(Screen.width/20,30,58),fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};subtitle=new GUIStyle(GUI.skin.label){fontSize=Mathf.Clamp(Screen.width/48,15,23),alignment=TextAnchor.MiddleCenter};button=new GUIStyle(GUI.skin.button){fontSize=Mathf.Clamp(Screen.width/44,16,25),fontStyle=FontStyle.Bold};small=new GUIStyle(GUI.skin.label){fontSize=13,alignment=TextAnchor.MiddleCenter};panel=new GUIStyle(GUI.skin.box);heroName=new GUIStyle(title){fontSize=Mathf.Clamp(Screen.width/24,26,44)};}
}
}
